







UPDATE PRODUCT_MODULE_MAST SET status = 0 WHERE module_id = 1400;

UPDATE PRODUCT_MODULE_MAST SET ALIAS_SMALL=ALIAS;




VALUES(<PRODUCT_ID_VALUE>, 100, 5100, '{"DB_TYPE": "4", "HEADING": [[{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "_$dateHeading$_", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Received", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Disconnected", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Completed", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Rejected", "ROWSPAN": "1"}]], "REPORT_ID": "100", "BACK_BUTTON": "loadBackPageWithDate(1,'''''''')", "DATE_FILTER": "H,M,Y", "QUERY_INPUT": {"H": "SELECT TO_CHAR(GEN_DATE, ''HH24'') AS C1, SUM(TOT_INCOMING_CALL_RECEIVED) AS C2, SUM(TOT_INCOMING_CALL_ANSWERED) AS C3, SUM(TOT_INCOMING_CALL_DISCONNECTED) AS C4, SUM(TOT_INCOMING_CALL_COMPLETED) AS C5, SUM(TOT_INCOMING_CALL_REJECTED) AS C6 FROM IVR_MIS_CONTENT_CUMULATIVE WHERE GEN_DATE BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_DATE, ''HH24'') ORDER BY TO_CHAR(GEN_DATE, ''HH24'')", "M": "SELECT TO_CHAR(GEN_DATE, ''YYYY-MM-DD'') AS C1, SUM(TOT_INCOMING_CALL_RECEIVED) AS C2, SUM(TOT_INCOMING_CALL_ANSWERED) AS C3, SUM(TOT_INCOMING_CALL_DISCONNECTED) AS C4, SUM(TOT_INCOMING_CALL_COMPLETED) AS C5, SUM(TOT_INCOMING_CALL_REJECTED) AS C6 FROM IVR_MIS_CONTENT_CUMULATIVE WHERE GEN_DATE BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_DATE, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_DATE, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_DATE, ''MONTH'') AS C1, SUM(TOT_INCOMING_CALL_RECEIVED) AS C2, SUM(TOT_INCOMING_CALL_ANSWERED) AS C3, SUM(TOT_INCOMING_CALL_DISCONNECTED) AS C4, SUM(TOT_INCOMING_CALL_COMPLETED) AS C5, SUM(TOT_INCOMING_CALL_REJECTED) AS C6 FROM IVR_MIS_CONTENT_CUMULATIVE WHERE GEN_DATE BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_DATE, ''MONTH''), TO_CHAR(GEN_DATE, ''MM'') ORDER BY TO_CHAR(GEN_DATE, ''MM'')"}, "REPORT_NAME": "Snap Shot", "OTHER_FILTER": [], "PRODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C5"}, {"DISPLAY": "C6"}], "REPORT_HEADING": "Snap Shot"}'::jsonb);

VALUES(<PRODUCT_ID_VALUE>, 300, 5100, '{"DB_TYPE": "4", "HEADING": [[{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "_$dateHeading$_", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Received", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "3", "DISPLAY": "Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Rejected", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Duration[In sec]", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Average", "ROWSPAN": "2"}], [{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Answered"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Completed"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Disconnected"}]], "REPORT_ID": "500", "BACK_BUTTON": "loadBackPageWithDate(1,'''''''')", "DATE_FILTER": "H,M,Y", "QUERY_INPUT": {"H": "SELECT TO_CHAR(GEN_TIME, ''HH24'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0)::BIGINT AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN ''0.00'' ELSE TO_CHAR(ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::NUMERIC / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2), ''FM999999990.00'') END AS C8 FROM <IVR_MIS_SCHEMA>.IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND (''_$ShortCodeName$_'' = ''-1'' OR SHORT_CODE = TO_NUMBER(''_$ShortCodeName$_'')) GROUP BY TO_CHAR(GEN_TIME, ''HH24'') ORDER BY TO_CHAR(GEN_TIME, ''HH24'')", "M": "SELECT TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0)::BIGINT AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN ''0.00'' ELSE TO_CHAR(ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::NUMERIC / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2), ''FM999999990.00'') END AS C8 FROM <IVR_MIS_SCHEMA>.IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND (''_$ShortCodeName$_'' = ''-1'' OR SHORT_CODE = TO_NUMBER(''_$ShortCodeName$_'')) GROUP BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_TIME, ''Month'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0)::BIGINT AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN ''0.00'' ELSE TO_CHAR(ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::NUMERIC / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2), ''FM999999990.00'') END AS C8 FROM <IVR_MIS_SCHEMA>.IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND (''_$ShortCodeName$_'' = ''-1'' OR SHORT_CODE = TO_NUMBER(''_$ShortCodeName$_'')) GROUP BY TO_CHAR(GEN_TIME, ''Month''), TO_CHAR(GEN_TIME, ''MM'') ORDER BY TO_CHAR(GEN_TIME, ''MM'')"}, "REPORT_NAME": "Short Code", "OTHER_FILTER": [{"TYPE": "S", "DISPLAY": "Short Code", "FILTER_QUERY": {"QUERY": "SELECT DISTINCT ICU.SHORT_CODE AS C1, ISC.SHORT_CODE AS C2 FROM <IVR_MIS_SCHEMA>.IVR_MIS_CUMULATIVE ICU JOIN IVR_MIS_CUMULATIVE ISC ON TRIM(ICU.SHORT_CODE) = ISC.SHORT_CODE", "DATA_ID": "C1", "DATA_LABEL": "C2", "QUERY_PARAM_VALUE": "C1"}, "QUERY_PARAM_NAME": "ShortCodeName"}], "PRODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C5"}, {"DISPLAY": "C6"}, {"DISPLAY": "C7"}, {"DISPLAY": "C8"}], "REPORT_HEADING": "Short Code"}'::jsonb);


VALUES('IVR_MIS_CUMULATIVE', 'IVR_EVR_DETAILS', 'COUNT', 'D', 2, '<DB_USERNAME>', '<DB_PASSWORD>', '<DB_IP>', '<DB_NAME>', 'public', 'SELECT DATE_TRUNC(''hour'', GEN_TIME) AS GEN_TIME, evr_event AS EVR_EVENT, evr_cause AS EVR_CAUSE, evr_cause AS EVR_REASON, SHORT_CODE, COUNT(*) AS COUNT, SUM(DURATION) AS DURATION FROM <:EVR_TABLE> WHERE gen_time BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY  DATE_TRUNC(''hour'', GEN_TIME), evr_event, evr_cause, evr_reason, SHORT_CODE LIMIT 200');

VALUES('IVR_MIS_CONTENT_CUMULATIVE', 'IVR_EVR_DETAILS', 'TOT_INCOMING_CALL_RECEIVED,TOT_INCOMING_CALL_ANSWERED,TOT_INCOMING_CALL_DISCONNECTED,TOT_INCOMING_CALL_COMPLETED,TOT_INCOMING_CALL_REJECTED', 'D', 1, '<DB_USERNAME>','<DB_PASSWORD>','<DB_IP>','<DB_NAME>', 'public', 'SELECT DATE_TRUNC(''hour'', GEN_TIME) AS GEN_DATE, HOUR(GEN_TIME) AS GEN_HOUR, SHORT_CODE, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 1 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_RECEIVED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 3 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_ANSWERED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 4 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_DISCONNECTED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 13 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_COMPLETED, SUM(CASE WHEN EVR_EVENT = 1 AND EVR_CAUSE = 5 THEN 1 ELSE 0 END) AS TOT_INCOMING_CALL_REJECTED FROM <:EVR_TABLE> WHERE GEN_TIME BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY DATE_TRUNC(''hour'', GEN_TIME), HOUR(GEN_TIME), SHORT_CODE');



COMMIT;

